# Ledger API - one-shot setup for a fresh EC2 server (Ubuntu or Amazon Linux)
set -e
if command -v apt-get >/dev/null; then
  curl -fsSL https://deb.nodesource.com/setup_22.x | sudo -E bash -
  sudo apt-get install -y nodejs build-essential
else
  curl -fsSL https://rpm.nodesource.com/setup_22.x | sudo bash -
  sudo dnf install -y nodejs gcc-c++ make
fi
mkdir -p ~/ledger-api && cd ~/ledger-api
echo '' | base64 -d | tar xzf -
npm install --omit=dev
sudo npm install -g pm2
pm2 delete ledger 2>/dev/null || true
pm2 start src/server.js --name ledger
pm2 save
sudo env PATH=$PATH $(which pm2) startup systemd -u $USER --hp $HOME
echo "DONE -> test with: curl http://localhost:3000/health"
